insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('identify-your-engine','engine','Identify the engine before choosing a procedure','bentley-e34-upload','Foreword p. v; 100-1; PDF 5,43',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"slug":"identify-your-engine","title":"Identify the engine before choosing a procedure","system":"engine","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"5 min read","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"reference","summary":"Match a car to the manual''s engine families and record what is still unknown before opening a repair or ordering a part.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"Foreword p. v; 100-1","pdfPages":[5,43]},"tools":["Vehicle records","Camera or notebook"],"cautions":["A model badge or model year alone does not prove which engine is currently installed.","This source establishes U.S. applications only; a swap needs its own identification evidence."],"steps":[{"title":"Record the actual vehicle","body":"Save the model, market, model year and available production date. Keep an unknown value explicitly unknown.","check":"The vehicle record distinguishes an observed fact from an assumption."},{"title":"Choose a source-supported starting point","body":"The manual groups U.S. 1989-1990 525i with M20, 1991-1992 525i with M50, and 1993-1995 525i with M50TU. Its 535i uses M30, and its 1994-1995 530i/540i use M60.","check":"A starting engine family is selected, or no supported match is claimed."},{"title":"Check the car against its history","body":"Compare the starting point with existing engine identification records and any documented modifications. Resolve a mismatch before using engine-specific instructions.","check":"The guide filter reflects the installed engine or remains unconfirmed."},{"title":"Carry the identity forward","body":"Attach the vehicle and engine family to your repair question and parts inquiry. Verify production restrictions separately before purchasing.","check":"Other members can see the configuration and unresolved details."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('cooling-system-visual-check','cooling','Start an overheating investigation with a cold inspection','bentley-e34-upload','170-1 to 170-2; PDF 205,206',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"slug":"cooling-system-visual-check","title":"Start an overheating investigation with a cold inspection","system":"cooling","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"15-25 min","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"inspection","summary":"Create a useful first record of coolant loss, belt condition, hoses and radiator airflow before treating a suspected component as a confirmed failure.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-1 to 170-2","pdfPages":[205,206]},"tools":["Inspection light","Eye protection","Gloves","Notebook or camera"],"cautions":["Wait until the engine and cooling system are fully cold. Never open a hot or pressurized coolant cap.","Keep coolant away from people and animals and contain any spill.","Keep hands clear of fans and belts; the electric fan can operate when the ignition is on."],"steps":[{"title":"Make the work area safe","body":"Park securely, switch the engine and ignition off, and let the system cool completely. This is a visual inspection; do not start a hot-system test.","check":"The engine is off, the key is removed, and the system is cold."},{"title":"Record level and visible leakage","body":"Observe the available cold-level markings and look for wet areas or dried residue around the engine, expansion tank, radiator and hose connections. Do not assume the first wet area is the source.","check":"Each observation has a location and a photo or written description."},{"title":"Look over hoses and the drive belt","body":"Check accessible hoses for cracking or obvious deterioration, inspect clamp areas for leakage, and look at the coolant-pump drive belt for visible damage.","check":"Any damaged or uncertain item is recorded for a closer engine-specific inspection."},{"title":"Inspect the radiator air path","body":"Look for dirt, leaves or debris obstructing the radiator and record any obvious damage. Keep tools and fingers outside the fan area.","check":"The record distinguishes an airflow obstruction from a coolant-flow suspicion."},{"title":"Choose the next test from the evidence","body":"A visual check cannot rule out an internal leak, circulation fault or fan-control fault. Take the recorded observations to the appropriate test or a qualified workshop.","check":"The next action is a test supported by an observation, rather than an unverified parts replacement."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('cooling-fan-airflow-check','cooling','Separate an airflow concern from a fan diagnosis','bentley-e34-upload','170-1; 170-3; PDF 205,207',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"slug":"cooling-fan-airflow-check","title":"Separate an airflow concern from a fan diagnosis","system":"cooling","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"10-15 min","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"inspection","summary":"Understand the mechanical fan and auxiliary electric fan, then gather cold, engine-off observations useful for an overheating-at-idle question.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-1; 170-3","pdfPages":[205,207]},"tools":["Inspection light","Notebook or camera"],"cautions":["Perform this visual inspection with a cold engine, ignition off and air conditioning off.","Never try to stop a moving fan or reach into its blades.","No powered fan test, connector bridging or hot-engine test is included here."],"steps":[{"title":"Describe when the symptom happens","body":"Record whether the reported overheating happens at idle, in traffic, at speed or under load. The manual identifies primary-fan faults as one possible cause of overheating during prolonged idling.","check":"The report includes conditions and observations without asserting a failed part."},{"title":"Identify the two fan arrangements","body":"From a safe view with the engine off, locate the pump-driven primary fan and the electric auxiliary fan ahead of the radiator. The fan clutch regulates the primary fan coupling.","check":"The question names the fan being discussed instead of using an ambiguous \"fan\" label."},{"title":"Inspect visible condition","body":"Look for damaged blades, obstructions and visible fluid leakage near the viscous clutch. Record what is visible without reaching into the fan assembly.","check":"Photos or notes identify the observed issue and its location."},{"title":"Escalate to the appropriate controlled test","body":"A still fan alone is not proof of a fault. Use the engine-specific fan-check procedure and wiring evidence for the next test, or ask a workshop to perform it.","check":"The next test is chosen; the observation has not been marked as a verified diagnosis."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('m50-water-pump-job-planning','cooling','Plan an M50 coolant-pump job','bentley-e34-upload','170-8 to 170-9; PDF 212,213',array['M50','M50TU']::text[],'draft','{"slug":"m50-water-pump-job-planning","title":"Plan an M50 coolant-pump job","system":"cooling","engines":["M50","M50TU"],"level":"Intermediate","duration":"10 min planning","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"planning","summary":"Prepare the correct engine-specific procedure, access tools and sealing parts before beginning coolant-pump work. This checklist is job planning, not a stand-alone replacement procedure.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-8 to 170-9","pdfPages":[212,213]},"tools":["Full engine-specific service procedure","Parts and tool checklist","Coolant containment plan"],"cautions":["Do not open or drain a hot cooling system.","The fan-clutch attachment uses a left-hand thread; consult the proper removal procedure before applying force.","Installation loads, tightening specifications, coolant choice and bleeding must be verified for the actual vehicle and replacement parts."],"steps":[{"title":"Confirm the M50 application","body":"Check the installed engine identity and review the M50-specific pump procedure rather than borrowing the M20, M30 or M60 steps.","check":"The engine and any modification are recorded."},{"title":"Plan access before draining","body":"The source procedure requires attention to the fan and shroud, coolant hoses, belt and pump pulley. Check that the required access tools and complete instructions are available.","check":"The work can proceed safely without improvising a missing holding or access tool."},{"title":"Match the pump and sealing parts","body":"Verify the pump application and obtain the correct new seal. This page does not supply a proven OEM number or current manufacturer material recommendation.","check":"The replacement and seal have documented fitment for the car."},{"title":"Preserve the installation cautions","body":"The source warns that drawing the pump in unevenly can damage the pump or timing-chain cover. Keep the complete tightening sequence and specifications with the job.","check":"The installer has the full method and vehicle-specific specifications."},{"title":"Plan completion checks","body":"The source calls for refilling and bleeding after reassembly. Include leak checks, coolant-level rechecks and a controlled functional check in the full work plan.","check":"The job checklist includes completion verification rather than ending when the new part is installed."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('battery-connections-first-check','electrical','Inspect battery cables and grounds before blaming the alternator','bentley-e34-upload','121-1; PDF 163',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"slug":"battery-connections-first-check","title":"Inspect battery cables and grounds before blaming the alternator","system":"electrical","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"15 min","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"inspection","summary":"Gather the basic connection, ground and belt observations that help a charging or slow-cranking investigation.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"121-1","pdfPages":[163]},"tools":["Inspection light","Eye protection","Gloves","Notebook or camera"],"cautions":["Battery acid and explosive charging gas require eye and skin protection and no sparks, smoking or flame.","Do not bridge battery terminals with tools or jewelry.","This page does not instruct battery disconnection, charging or live electrical testing."],"steps":[{"title":"Find the battery for this configuration","body":"The source locates it in the engine compartment on U.S. 1989-1991 525i and under the rear seat on 1992-on 525i and the covered 530i, 535i and 540i. Confirm the actual installation.","check":"The location is observed on the car and any modification is recorded."},{"title":"Inspect without disturbing the connections","body":"With the ignition off, look for visible corrosion, cable damage and an obviously loose connection. Avoid touching both terminals or placing a tool between a terminal and bodywork.","check":"Visible connection issues are documented, not hidden by an immediate parts swap."},{"title":"Follow the ground path visually","body":"Inspect accessible battery-to-body and engine-to-body ground connections for damage or corrosion. Do not infer electrical continuity from appearance alone.","check":"The report identifies which ground connection was observed."},{"title":"Check the alternator belt visually","body":"With the engine stopped, inspect the accessible belt for obvious wear or damage. Belt adjustment and replacement require the applicable engine procedure.","check":"Belt condition is recorded separately from battery or alternator condition."},{"title":"Request the next measurement","body":"If the cause remains unclear, use a suitable charging-system diagnostic procedure or workshop test. A visual inspection alone cannot certify battery capacity or alternator output.","check":"The next step is a defined measurement with the vehicle identity attached."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('front-strut-component-identification','suspension','Identify a front strut assembly and its production differences','bentley-e34-upload','310-1 to 310-4; PDF 277,278,279,280',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"slug":"front-strut-component-identification","title":"Identify a front strut assembly and its production differences","system":"suspension","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"8 min read","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"reference","summary":"Learn the front-suspension component names and why the upper strut stack must be checked against the car''s configuration.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"310-1 to 310-4","pdfPages":[277,278,279,280]},"tools":["Vehicle production information","Parts diagram or camera"],"cautions":["Do not loosen the strut shaft nut or disassemble a spring-loaded assembly for identification.","Spring work requires suitable equipment and the complete procedure.","Do not treat a visual teaching diagram as a fitment guarantee."],"steps":[{"title":"Distinguish the nearby components","body":"The front suspension includes the strut, control arm, thrust arm, stabilizer link, crossmember and center tie rod. Use these names to locate the subject of a noise or parts question.","check":"The report identifies a component or clearly states that its location is uncertain."},{"title":"Read the strut as an assembly","body":"The strut stack includes the mount, spring seats and pads, spring, cartridge and housing; the bump stop and protective tube are additional service items.","check":"The requested item is not confused with the entire strut assembly."},{"title":"Check the production split","body":"The manual shows different upper stacks for 1989-1992 and 1993-on applications. It also notes that some mounts correct camber and carry a plus or minus marking.","check":"Production information and any observed mount marking are included with the inquiry."},{"title":"Verify fitment before ordering","body":"Check the car''s actual strut and mount configuration, including prior modifications, against documented parts applicability. The source diagram does not establish an OEM number for every item.","check":"The part remains unconfirmed until the vehicle and catalog evidence agree."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('engine-air-filter-replacement','engine','Replace the engine air filter','bentley-e34-upload','020-10, Figs. 5–6; PDF 32',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"engine-air-filter-replacement","title":"Replace the engine air filter","system":"engine","kind":"replacement","duration":"15–25 min","summary":"Open the factory clip-fastened airbox, replace the element and check the perimeter seal before starting the engine.","applicability":"Bentley-covered U.S. 525i, 535i, 530i and 540i with the original two-piece, spring-clipped intake housing. Confirm the installed housing and element on cars with intake changes.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-10, Figs. 5–6","pdfPages":[32]},"tools":["Correct engine air filter element","Clean lint-free cloth","Light"],"cautions":["Switch the ignition off and let the engine cool. Keep grit and tools clear of the clean-side intake opening.","Support the airbox lid and attached intake duct. Stop if age-hardened plastic or wiring prevents access without force."],"steps":[{"title":"Locate the airbox and check the replacement","body":"Follow the intake duct to its rectangular filter housing. Bentley locates the M20/M50 housing at the left front and the M30/M60 housing at the right front, using vehicle left and right. Confirm the element against the installed housing.","check":"The replacement matches the filter outline, depth and sealing lip."},{"title":"Release the perimeter clips","body":"Note how the upper lid locates in the lower housing. Release the spring clips around the joint and lift the lid only far enough to withdraw the filter. Keep the lid supported so it does not pull on the duct or airflow-meter wiring.","check":"The filter lifts out without straining a hose, wire or clip."},{"title":"Clean the housing and seat the element","body":"Note which side of the old filter faced incoming air. Wipe dirt from the housing with a lint-free cloth, keeping debris out of the outlet to the engine. Seat the replacement in the same orientation and follow any locating features on its frame.","check":"The filter lies flat and the seal follows the housing edge with no fold or gap."},{"title":"Close and inspect the intake","body":"Engage the lid locators, lower the lid evenly and refasten each clip. Check the attached intake duct and connector for anything disturbed during access. Remove the cloth and tools before starting.","check":"The airbox joint is closed all around and every fastener and disturbed connection is secure."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('windshield-wiper-blade-replacement','electrical','Replace the front windshield wiper blades','bentley-e34-upload','020-18 and 611-1 to 611-2, Fig. 1; PDF 40,387,388',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"windshield-wiper-blade-replacement","title":"Replace the front windshield wiper blades","system":"electrical","kind":"replacement","duration":"15–20 min","summary":"Release the original front blade retainers, seat each replacement and check sweep and park on wet glass.","applicability":"Front windshield blade assemblies on Bentley-covered U.S. E34s with the retainer shown in group 611. Check both blade lengths and adapters. Touring rear blades, rubber inserts and wiper-arm adjustment are separate jobs.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-18 and 611-1 to 611-2, Fig. 1","pdfPages":[40,387,388]},"tools":["Correct left and right blade assemblies","Folded towel","Water or washer fluid"],"cautions":["Park the wipers and turn the ignition off before lifting an arm. Hold the spring-loaded arm whenever the blade is off.","Lay a folded towel on the glass under the arm. Stop if the arm will not lift freely or the new adapter does not latch."],"steps":[{"title":"Match the attachment on each arm","body":"Compare blade lengths and the attachment to the installed hardware. Work on one side at a time and identify the spring tab or pair of tabs before releasing the blade.","check":"The correct replacement is ready for this arm and its latch matches."},{"title":"Release the blade without dropping the arm","body":"Lift the arm off the protected windshield. Turn the blade roughly across the arm to reach the latch. Hold the arm steady, press the retaining tab or tabs and slide the blade out of the attachment.","check":"The old blade is free and the bare arm is still supported above the glass."},{"title":"Fit and test the new blade lock","body":"Slide the new assembly into the mount until its retainer engages. Gently pull against the latch by hand before lowering the arm onto the glass. Repeat for the other side.","check":"Neither blade slides out, and both sit normally against the windshield."},{"title":"Verify sweep and park","body":"Remove the towel, wet the glass and test the wipers from the driver’s seat with hands clear. Check both blades for clearance through the sweep and see whether they return to their parked position. Stop if a blade moves on the arm, strikes trim or leaves visibility impaired.","check":"Both blades stay attached, wipe cleanly and return to park without interference."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('accessory-drive-belt-inspection','engine','Inspect accessory drive belts for wear','bentley-e34-upload','020-12 to 020-13, Figs. 9–11; PDF 34,35',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"accessory-drive-belt-inspection","title":"Inspect accessory drive belts for wear","system":"engine","kind":"inspection","duration":"10–20 min","summary":"Identify the visible belt arrangement and check for glazing, cracking, separation, contamination or poor tracking with the engine off.","applicability":"Factory accessory drives on the covered U.S. E34 engines. Bentley groups M20/M30 V-belts separately from M50/M60 poly-ribbed belts. Verify the actual tensioner and routing before any replacement.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-12 to 020-13, Figs. 9–11","pdfPages":[34,35]},"tools":["Flashlight","Inspection mirror","Camera"],"cautions":["Engine off, key out and engine cool. Keep hands and tools clear of fans, belts and pinch points.","This check is visual. Releasing a tensioner or turning the engine to expose the rest of a belt requires its own procedure."],"steps":[{"title":"Separate the accessory belts from the timing drive","body":"Identify the visible belts driving accessories at the front of the engine. Note the narrow V-profile or multiple small ribs, and count the visible belts. The M20 camshaft belt under its cover is outside this inspection.","check":"You have recorded the belt type and the visible route for each accessory belt."},{"title":"Inspect each accessible span","body":"Use a light and mirror to inspect the visible faces and edges. Look for polished contact surfaces, cracks, loose strands, separated layers, missing ribs or wet oil. Record which surfaces you could see and which remained hidden.","check":"Photos identify the affected belt, location and type of damage."},{"title":"Check belt seating and nearby traces","body":"Look for a belt riding at an angle, on a pulley edge or outside its expected grooves. If there is fluid on the belt, look for traces above or beside it from a safe position. Note a reported squeal separately from the visible condition.","check":"The record separates belt condition, seating and any possible leak."},{"title":"Decide what needs further work","body":"A torn, displaced or contaminated belt needs assessment before the engine is run again. Establish the correct routing, belt and tensioning hardware before replacement, and address the source of contamination. Do not use belt dressing to mask a squeal.","check":"The next action accounts for the specific belt and observed fault."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('brake-fluid-level-inspection','brakes','Check the brake and clutch fluid reservoir','bentley-e34-upload','020-15, Fig. 16; 020-16; PDF 37,38',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"brake-fluid-level-inspection","title":"Check the brake and clutch fluid reservoir","system":"brakes","kind":"inspection","duration":"5–10 min","summary":"Read the brake reservoir level through the wall and document a low or falling level for hydraulic diagnosis.","applicability":"Bentley-covered U.S. E34s with the original marked brake-fluid reservoir. On manual-transmission cars the brake reservoir also feeds the hydraulic clutch. This is an external level check.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-15, Fig. 16; 020-16","pdfPages":[37,38]},"tools":["Flashlight","Camera or service log"],"cautions":["Keep the reservoir closed. Fluid is poisonous and can damage painted surfaces.","If the level is below MIN, there is an active leak, or the pedal is soft or sinking, do not drive. Arrange inspection and recovery."],"steps":[{"title":"Identify the correct reservoir","body":"Park on level ground with the engine off. Find the reservoir at the brake master cylinder. Verify its markings and distinguish it from the coolant and steering reservoirs.","check":"The MIN and MAX marks you are reading are on the brake-fluid reservoir."},{"title":"Read the level against both marks","body":"Look squarely at the marked wall using a light. Record the level in relation to MIN and MAX and whether the marks and fluid line were visible. If you cannot read it reliably, leave the observation unresolved.","check":"The record includes a visible level and date, or states that the reading was inconclusive."},{"title":"Capture any symptoms and change over time","body":"Note any warning lamp, change in pedal behavior or visible wetness near the reservoir or hydraulic connections. A gradual change can accompany pad wear, while a low or falling level also warrants a leak check. On a manual car include any change in clutch behavior.","check":"The next inspection can distinguish brake wear, brake hydraulic leakage and possible clutch hydraulic leakage."},{"title":"Route a low reading to diagnosis","body":"Keep a dated photo and describe the level and symptoms together. Use the brake and clutch source sections as applicable to have the loss investigated before returning the car to service.","check":"A low reading remains open until its cause is resolved."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('power-steering-fluid-level-inspection','suspension','Identify and check the power-steering fluid','bentley-e34-upload','020-15, Fig. 15; PDF 37',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"power-steering-fluid-level-inspection","title":"Identify and check the power-steering fluid","system":"suspension","kind":"inspection","duration":"10–15 min","summary":"Read the reservoir marking and dipstick on the applicable steering system, then record the level and any evidence of leakage.","applicability":"Bentley-covered U.S. E34s with a labeled reservoir and MIN/MAX dipstick as shown in Fig. 15. Verify the installed hydraulic configuration and any shared systems before using a service procedure.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-15, Fig. 15","pdfPages":[37]},"tools":["Clean lint-free cloth","Flashlight","Camera"],"cautions":["Use level ground, engine off. Clean around the cap before opening and keep dirt out of the reservoir.","ATF and CHF systems require different fluids. Verify the installed system and applicable specification before adding anything."],"steps":[{"title":"Confirm the reservoir identity","body":"Find the steering-fluid reservoir and read its marking before opening it. Record the label exactly and note whether the car has shared hydraulic equipment or replacement parts. A faded or missing label leaves fluid identity unresolved.","check":"The reservoir is identified and its label or lack of one is documented."},{"title":"Read the dipstick marks","body":"On the source-shown unit, remove the cap and inspect the integral dipstick. Use the matching vehicle procedure for the dipstick seating and read the fluid line against the MIN and MAX marks. Refit the cap securely by hand.","check":"The reading is recorded with its conditions, and the cap is back in place."},{"title":"Look for a source of loss","body":"From above, inspect the reservoir and accessible hose connections for fresh wetness. Note any recent fluid additions, steering noise or change in assistance. A level check alone cannot identify a bad pump or steering box.","check":"Low or falling level, leaks or loss of assistance have a separate diagnosis before further use."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('cold-tire-pressure-check','suspension','Check and set cold tire pressures','bentley-e34-upload','020-16, tire inflation; PDF 38',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"cold-tire-pressure-check","title":"Check and set cold tire pressures","system":"suspension","kind":"inspection","duration":"10–15 min","summary":"Match the door-pillar placard to your tires and load, measure each wheel cold and track repeat losses.","applicability":"Factory tire sizes and load combinations listed for the actual vehicle. For a non-listed tire size, confirm the correct cold settings for the installed combination before adjusting.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-16, tire inflation","pdfPages":[38]},"tools":["Tire pressure gauge","Air supply","Driver-door pillar placard or matching owner’s manual"],"cautions":["Check when the tires are cold. Use the vehicle’s cold pressure for the applicable axle and load, within the tire’s limits.","Do not bleed a hot tire down to the cold target. A visibly damaged tire or one that will not hold pressure needs inspection before driving."],"steps":[{"title":"Read the correct placard row","body":"Compare the front and rear tire sizes with the driver-door pillar placard or matching owner’s manual. Choose the load condition that applies and record both axle targets in the units shown.","check":"You have a verified front and rear cold target for the actual tire sizes and load."},{"title":"Measure before adding air","body":"Wait at least three hours after driving for a cold reading. Remove each valve cap and seat the gauge squarely until the reading stabilizes. Record the four readings by wheel position and note any one tire substantially lower than the rest.","check":"All four readings and their units are recorded before adjustment."},{"title":"Set each tire and recheck it","body":"Adjust in short increments to the appropriate axle target, rechecking with the same gauge. Refit the valve caps. If the car has a serviceable spare, check it separately against its own specified pressure.","check":"Each wheel is at its verified target and each valve has its cap."},{"title":"Follow up on repeat loss","body":"Save the date, ambient conditions and readings. If one tire repeatedly loses more pressure than the others, have the tire, valve and wheel inspected for leakage. A pressure adjustment does not repair a puncture or damaged sidewall.","check":"The next cold measurement can be compared wheel by wheel."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('m50-engine-oil-and-filter','engine','Change the oil and cartridge filter on an M50 525i','bentley-e34-upload','020-8 to 020-10, Table e and Figs. 3–4; PDF 30,31,32',array['M50','M50TU']::text[],'draft','{"engines":["M50","M50TU"],"level":"Intermediate","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"m50-engine-oil-and-filter","title":"Change the oil and cartridge filter on an M50 525i","system":"engine","kind":"replacement","duration":"45–75 min","summary":"Drain the engine oil, renew the cartridge and seals, then verify oil pressure, level and leaks before driving.","applicability":"U.S. E34 525i with an installed M50 or M50TU and factory-type sump and cartridge housing. Confirm the actual drain plug and filter lid hardware. The M20 spin-on filter and aftermarket sump or housing hardware use different instructions.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"020-8 to 020-10, Table e and Figs. 3–4","pdfPages":[30,31,32]},"tools":["Correct cartridge and seal kit","New drain-plug sealing washer","Suitable engine oil","Drain pan and funnel","Sockets, torque wrench and clean lint-free cloths","Oil-resistant gloves and eye protection"],"cautions":["Use firm, level ground and immobilize the car. Never get under a car supported only by a jack. If you need to lift it, use the approved lifting and support points and the procedure in Bentley 010.","Warm oil drains quickly and can burn. Keep hands clear of the stream. Let the oil cool enough to handle safely.","If the pressure warning stays on after starting, shut the engine off immediately and resolve the cause before restarting."],"steps":[{"title":"Confirm the filter, seals and tightening values","body":"Identify the sump drain plug and the actual cartridge cover fastener before opening either. Bentley 020-9 lists 25 Nm for an original M12 sump plug and 60 Nm for M22. It lists 33 Nm for an M10/M12 filter-cover bolt and 25 Nm for a screw-on cover. These are different fasteners. Confirm the installed hardware and use its applicable instructions if it differs.","check":"The drain plug and cover each have their own confirmed value, and the filter, new washer and all applicable O-rings are on hand."},{"title":"Drain the sump and refit the plug","body":"Warm the engine briefly, switch it off and position the pan to catch the full stream. Identify the engine sump independently of the transmission. Release the plug, drain the oil and clean the mating face. Install the plug by hand with its new washer, then tighten to the confirmed value.","check":"The plug started cleanly by hand and the new washer is seated. A damaged thread or sealing face stops the job."},{"title":"Replace the cartridge and seals","body":"Remove the filter cover and lift out the old cartridge. Note the exact grooves for the cover and center-bolt seals, where fitted. Replace each old seal, lubricate the new seals with clean engine oil and seat the new element. Refit and tighten the cover using the confirmed value for that housing.","check":"No old seal remains in a groove. Each new seal sits flat and the lid is fully seated."},{"title":"Refill by the dipstick","body":"With the car level, add suitable oil in stages. Bentley lists about 5.75 L for the M50 with a filter change. Residual oil and hardware changes affect the amount needed. Check the dipstick after the oil settles and leave the reading within the marked range before starting.","check":"Filler cap and dipstick are in place and the level is in range."},{"title":"Check pressure, leaks and final level","body":"Start from the driver’s seat and watch the oil pressure warning. Stop immediately if it stays on. Once normal pressure is indicated, check for fresh leaks from a safe position. Switch off, allow the oil to settle, recheck on level ground and correct the level in small amounts. Recycle the used oil and filter at an appropriate collection point.","check":"Warning clears, drain and housing are dry, and the final dipstick reading is in range."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('factory-halogen-headlight-bulb','electrical','Replace a factory twist-lock halogen headlight bulb','bentley-e34-upload','630-1 to 630-2, Figs. 1–2; 121-1; PDF 163,407,408',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"factory-halogen-headlight-bulb","title":"Replace a factory twist-lock halogen headlight bulb","system":"electrical","kind":"replacement","duration":"15–30 min","summary":"Identify the failed beam, access the rear of the lamp and verify the replacement is fully seated before testing.","applicability":"Source-matching factory U.S. halogen housings with the rear quarter-turn bulb mount shown in Bentley 630. Check the actual lamp and bulb specification. Other retention systems and HID or LED conversions need their own procedure.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"630-1 to 630-2, Figs. 1–2; 121-1","pdfPages":[163,407,408]},"tools":["Correct halogen bulb for the installed housing","Screwdriver for the rear cover","Clean gloves and a light","Tool for the negative battery terminal"],"cautions":["Turn off the lamps and ignition and let the bulb cool. Follow Bentley 121 for safe negative-battery cable isolation and any radio-code preparation.","Handle halogen bulbs by their base. Do not use this method on high-voltage retrofit lighting or force a mismatched socket."],"steps":[{"title":"Identify the lamp and verify the bulb","body":"Identify which side and beam failed before isolating the battery. Confirm the replacement specification and connector against the housing and vehicle information.","check":"You have the correct replacement for that position and the electrical supply is isolated."},{"title":"Open rear access","body":"Under the bonnet, remove the protective cover behind the headlight. On the driver’s side, move the alternator cooling duct first if it blocks the cover. Keep the cover screws and duct hardware together.","check":"The rear bulb base is accessible without disturbing the headlamp adjusters."},{"title":"Release the old bulb and seat the new one","body":"Looking at the lamp from behind, turn the original bulb base counterclockwise a quarter turn. Withdraw it and release the connector at its latch. Compare the old and new tabs. Reconnect the replacement, align the tabs with the housing slots and lock it with a clockwise quarter turn.","check":"The base sits flush, turns to its stop and has no play. The connector is latched."},{"title":"Restore the covers and verify the beam","body":"Refit the protective cover and any duct removed. Restore the battery connection per the applicable procedure. Test low and high beams, watch for a bulb warning and compare the projected pattern with the opposite side. An abnormal pattern or recurring warning needs inspection before driving in low visibility.","check":"Both beams operate as expected, covers are secure and the repaired bulb does not sit crooked."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('sedan-tail-lamp-bulb','electrical','Replace a body-mounted tail lamp bulb on an E34 Sedan','bentley-e34-upload','630-1, electrical precautions; 630-4, Fig. 10; 121-1; PDF 163,407,410',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"sedan-tail-lamp-bulb","title":"Replace a body-mounted tail lamp bulb on an E34 Sedan","system":"electrical","kind":"replacement","duration":"10–20 min","summary":"Access the original twist-lock holder behind the trunk liner and verify the replacement lamp function.","applicability":"Bentley-covered U.S. E34 Sedan with the body-mounted rear lamp and removable quarter-turn socket shown in group 630. Excludes Touring, trunk-lid and center high-mounted lamp assemblies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"630-1, electrical precautions; 630-4, Fig. 10; 121-1","pdfPages":[163,407,410]},"tools":["Replacement bulb matched to the position and rating","Light","Tool for the negative battery terminal"],"cautions":["Switch off the lamps and ignition, allow the bulb to cool and isolate the negative battery terminal per the vehicle procedure.","Stop for melted contacts, water intrusion or brittle wiring. A new bulb will not repair a damaged socket."],"steps":[{"title":"Identify the failed function","body":"With the car parked, confirm whether the tail, brake or another rear lighting function is affected. Match the bulb’s base, contact count and rating to that position before fitting a replacement.","check":"The bulb and lamp position are identified, and power is isolated before disassembly."},{"title":"Reach and remove the holder","body":"Release the side liner retainer in the trunk and pull the liner aside. Grip the holder rather than the wires. Turn the holder a quarter turn to unlock it, then pull it out of the body-mounted lens.","check":"The correct holder is free and the wiring and lens are undamaged."},{"title":"Install the bulb and lock the holder","body":"Press the old bulb gently into its bayonet socket and turn it counterclockwise to release it. Match the new bulb pins to the socket slots, press and turn it into lock. Refit the holder and secure the liner.","check":"The bulb stays seated and the holder locks without forcing it."},{"title":"Verify the lighting","body":"Restore the battery connection and test the affected function. Use a helper or a safe reflection for brake lamps. Check the other functions on that housing and record any remaining warning.","check":"The repaired lamp and the other affected housing functions work before the car is driven."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values('front-door-window-dropped-inspection','body','Check a front door window that dropped or sits crooked','bentley-e34-upload','512-1, Figs. 1–2 and chapter contents; PDF 353',array['M20','M30','M50','M50TU','M60']::text[],'draft','{"engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","reviewStatus":"draft","sourceChecked":true,"durationBasis":"Editorial estimate for the listed task on accessible original equipment.","slug":"front-door-window-dropped-inspection","title":"Check a front door window that dropped or sits crooked","system":"body","kind":"inspection","duration":"5–10 min","summary":"Record the glass position and symptoms without cycling a loose window. Identify the right source section for slides, regulator or motor work.","applicability":"Front door glass on Bentley-covered U.S. E34s. This check uses external observations only. Removing the glass, liner or regulator requires a separate procedure and support for the glass.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"512-1, Figs. 1–2 and chapter contents","pdfPages":[353]},"tools":["Light","Camera or service log"],"cautions":["Leave the window switch off if the glass is loose, tilted or jammed. Keep fingers out of the slot and regulator path.","Broken or unsupported glass requires safe handling and support before the door is opened up. Do not slam the door to test it."],"steps":[{"title":"Record where the glass stopped","body":"With the ignition off, record which door is affected and whether the glass is below the seal, tilted or loose. Note any click, motor noise or slow movement that you heard before the failure, without repeating the test on a loose window.","check":"A photo and description identify the door and glass position without operating the mechanism."},{"title":"Separate the glass support from the drive","body":"The manual shows two slides with retaining clips at the lifting-arm connections on the front glass. A loose window is reason to inspect these connections and guides once the glass is safely supported. A silent drive can also require an electrical check. The symptom alone does not identify a failed part.","check":"The report keeps glass support, regulator movement and motor operation separate."},{"title":"Choose the next source and protect the car","body":"Use chapter 512 for front glass and regulator procedures and chapter 411 for door trim access. Arrange safe support or repair if the glass cannot be secured. Share the exact door, symptoms and prior work before ordering a slide, regulator or motor.","check":"The next step identifies what needs inspection and which manual group applies."}]}'::jsonb) on conflict(id) do update set content=excluded.content;
